POLICY_SOURCE = '"""Editable agent behavior, executed only inside the sandbox.\n\nThe optimizer may change this module\'s prompt, tools, helpers, context management,\nand run_agent loop. The runtime supplies model calls, bash execution and logging.\n"""\nimport json\n\nAGENT_INSTRUCTION = \'You are an autonomous terminal agent. You are given a task and a Linux container.\\nYou solve tasks by executing bash commands. Work step by step.\\n\\nRules:\\n- Read the task carefully before acting.\\n- Explore the environment first to understand what you have.\\n- Check command output for errors before proceeding.\\n- Install missing dependencies as needed.\\n- Verify your solution before finishing.\\n- When you are done, send a final text message (no tool call) summarizing what you did.\\n\'\nTOOLS = [{\'type\': \'function\', \'function\': {\n    \'name\': \'bash\', \'description\': \'Execute a bash command in the container. Returns stdout and stderr.\',\n    \'parameters\': {\'type\': \'object\', \'properties\': {\'command\': {\'type\': \'string\', \'description\': \'The bash command to execute.\'}}, \'required\': [\'command\']},\n}}]\n\nMAX_TOOL_LINES = 120\nMAX_TOOL_CHARS = 6000\nHEAD_LINES = 40\nTAIL_LINES = 20\n\n\ndef _compact_tool_output(text):\n    if len(text) <= MAX_TOOL_CHARS and text.count(\'\\n\') <= MAX_TOOL_LINES:\n        return text\n    lines = text.splitlines()\n    if len(lines) <= HEAD_LINES + TAIL_LINES:\n        compact = \'\\n\'.join(lines)\n    else:\n        omitted = len(lines) - HEAD_LINES - TAIL_LINES\n        compact = \'\\n\'.join(lines[:HEAD_LINES])\n        compact += f\'\\n... [{omitted} lines omitted; full output preserved in tool log] ...\\n\'\n        compact += \'\\n\'.join(lines[-TAIL_LINES:])\n    if len(compact) > MAX_TOOL_CHARS:\n        keep = max(0, (MAX_TOOL_CHARS - 120) // 2)\n        compact = (\n            compact[:keep]\n            + f\'\\n... [output truncated; {len(text)} chars total, full output preserved in tool log] ...\\n\'\n            + compact[-keep:]\n        )\n    if text.endswith(\'\\n\') and not compact.endswith(\'\\n\'):\n        compact += \'\\n\'\n    return compact\n\n\ndef run_agent(api, instruction):\n    messages = [{\'role\': \'system\', \'content\': AGENT_INSTRUCTION},\n                {\'role\': \'user\', \'content\': \'Task:\\n\' + instruction}]\n    while True:\n        message = api.model(messages, TOOLS)\n        messages.append(message)\n        calls = message.get(\'tool_calls\') or []\n        if not calls:\n            return\n        for call in calls:\n            try:\n                args = json.loads(call[\'function\'][\'arguments\'])\n                if call[\'function\'][\'name\'] != \'bash\' or not isinstance(args.get(\'command\'), str):\n                    raise ValueError(\'Invalid bash tool call\')\n                result = api.bash(args[\'command\'])\n            except (ValueError, TypeError) as exc:\n                result = str(exc)\n            result = str(result)\n            api.tool_result(call[\'id\'], result)\n            messages.append({\'role\': \'tool\', \'tool_call_id\': call[\'id\'], \'content\': _compact_tool_output(result)})\n'
